<?php defined('ABSPATH') || exit; $project=$args['project']; $featured=$args['featured']; $url=noir_project_link($project['project_id']); ?>
<article id="project-<?php echo esc_attr($project['project_id']); ?>" class="home-project<?php echo $featured?' home-project-featured':''; ?>" data-home-project><div class="home-project-visual">
<?php if ($featured && ($project['comparison']['before_image'] || $project['comparison']['after_image'])) { get_template_part('template-parts/comparison',null,['comparison'=>$project['comparison']]); } else { echo wp_get_attachment_image($project['image'],'large',false,['sizes'=>'(min-width: 1440px) 640px, (min-width: 768px) 48vw, calc(100vw - 48px)','loading'=>'lazy','fetchpriority'=>'auto']); } ?>
</div><div class="home-project-content"><?php if ($project['eyebrow']!=='') : ?><p class="small-label accent"><?php echo esc_html($project['eyebrow']); ?></p><?php endif; ?><h3><?php echo esc_html($project['title']); ?></h3><?php if ($project['vehicle']!==$project['title']) : ?><p class="accent"><?php echo esc_html($project['vehicle']); ?></p><?php endif; ?><?php if ($project['teaser']!=='') : ?><p class="muted"><?php echo esc_html($project['teaser']); ?></p><?php endif; ?><p class="muted"><?php echo esc_html($project['work']); ?></p>
<?php if ($project['facts'] || $project['finish']!=='') : ?><dl class="project-facts"><?php if ($project['finish']!=='') : ?><div><dt><?php esc_html_e('Color','noir-auto-detailing'); ?></dt><dd><?php echo esc_html($project['finish']); ?></dd></div><?php endif; ?><?php foreach ($project['facts'] as $fact) : ?><div><dt><?php echo esc_html($fact['label']); ?></dt><dd><?php echo esc_html($fact['value']); ?></dd></div><?php endforeach; ?></dl><?php endif; ?>
<?php if ($url) : ?><a class="text-link" href="<?php echo esc_url($url); ?>"><?php esc_html_e('View Gallery Showcase','noir-auto-detailing'); ?><span class="screen-reader-text"> — <?php echo esc_html($project['title']); ?></span><span aria-hidden="true"> →</span></a><?php endif; ?></div></article>
